/*
 * Método PMDF · acervo autoral por tópico (2026-11).
 * Não reproduz questões de bancas; não substitui leitura da legislação vigente.
 * CE editorial (uma assertiva fundamentada por tópico) e MC selecionadas.
 * Geração adicional: o motor local usa explicações autorais como fonte.
 */
(function(root){
 "use strict";
 const catalog=root.PMDF_PRACA_CATALOG;
 const packs=new Map(), used=new Set();
 const norm=s=>String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();
 const checkedUrl=url=>/^https:\/\/(?:www\d*\.)?(?:planalto\.gov\.br|gov\.br|www\.gov\.br|sinj\.df\.gov\.br|ibge\.gov\.br|bvsms\.saude\.gov\.br|portaldaobmep\.impa\.br|learnenglish\.britishcouncil\.org|scielo\.br|periodicos\.ufsc\.br|repositorio\.uniceub\.br|brasil\.un\.org|un\.org|ohchr\.org)(?:\/|$)/i.test(String(url||'')) ? url : '';
 function add(index, rows, source, multipleChoice=[]){
   if(!catalog)throw Error("Carregue o catálogo PMDF antes do banco autoral");
   const d=catalog.disciplinas[index-1];
   if(!d||packs.has(d.slug))throw Error("Disciplina inválida ou duplicada: "+index);
   if(!Array.isArray(rows)||rows.length!==d.assuntos.length)throw Error("Cobertura incompleta: "+d.nome);
   if(!checkedUrl(source?.url))throw Error("URL de referência inválida: "+d.nome);
   const questions=[];
   rows.forEach((r,i)=>{
     const [statement,answer,explanation,itemRef]=r;
     if(itemRef?.url && !checkedUrl(itemRef.url))throw Error("Referência inválida: "+d.nome+" #"+(i+1));
     if(!["C","E"].includes(answer)||String(statement).trim().length<75||String(explanation).trim().length<48)
       throw Error("Revisar item "+d.nome+" #"+(i+1));
     const a=d.assuntos[i],id=d.slug+"|"+a.slug+"|CE|1";
     if(used.has(id))throw Error("Duplicata "+id);
     used.add(id);
     questions.push(Object.freeze({
       id,coverageId:"programa-v1:"+id,type:"CE",
       statement:String(statement).trim(),answer,
       explanation:String(explanation).trim(),
       law:d.nome,topic:a.nome,disciplineSlug:d.slug,topicSlug:a.slug,
       lawBasis:itemRef?.label||source.label,sourceUrl:itemRef?.url||source.url,
       evidence:(answer==="C"?statement:explanation),
       origin:"curriculo-autoral",board:"Estilo Cebraspe · questão autoral",
       difficulty:"Médio"
     }));
   });
   for(const [topicIndex,statement,alternatives,answer,explanation] of multipleChoice){
     const a=d.assuntos[topicIndex-1];
     if(!a||!Array.isArray(alternatives)||alternatives.length!==5||
        new Set(alternatives.map(norm)).size!==5||!["A","B","C","D","E"].includes(answer)||
        String(statement).trim().length<55||String(explanation).trim().length<48)
       throw Error("Questão MC inválida: "+d.nome+" #"+topicIndex);
     const id=d.slug+"|"+a.slug+"|MC|1";
     if(used.has(id))throw Error("Duplicata "+id);used.add(id);
     questions.push(Object.freeze({
       id,coverageId:"programa-v1:"+id,type:"MC",
       statement,options:Object.freeze(alternatives),answer,explanation,
       law:d.nome,topic:a.nome,disciplineSlug:d.slug,topicSlug:a.slug,
       lawBasis:source.label,sourceUrl:source.url,origin:"curriculo-autoral",
       board:"Questão autoral · múltipla escolha",difficulty:"Médio"
     }));
   }
   packs.set(d.slug,Object.freeze({source:Object.freeze({...source}),questions:Object.freeze(questions)}));
 }
 function choose(dslug,aslug,format){
   const ds=dslug?[catalog.disciplina(dslug)].filter(Boolean):catalog.disciplinas;
   return ds.flatMap(d=>(packs.get(d.slug)?.questions||[]).filter(q=>
     (!aslug||q.topicSlug===aslug) &&
     (format==="MIX"||format===(q.type==="MC"?"MC":"CE"))
   ));
 }
 function guide(dslug,aslug){
   return (dslug?[catalog.disciplina(dslug)].filter(Boolean):catalog.disciplinas).map(d=>{
     const pack=packs.get(d.slug);
     const rows=(pack?.questions||[]).filter(q=>q.type==="CE"&&(!aslug||q.topicSlug===aslug))
       .map(q=>({article:q.topic,sourceText:String(q.evidence||"").trim(),
         plainExplanation:q.explanation,practicalExample:q.statement}));
     return {lawName:d.nome,articlesMapping:{highIncidence:rows,mediumIncidence:[],lowIncidence:[]},
       curriculum:true};
   }).filter(g=>g.articlesMapping.highIncidence.length);
 }
 root.PMDF_TOPIC_BANK=Object.freeze({
   add,choose,guide,
   count:()=>[...packs.values()].reduce((n,p)=>n+p.questions.length,0),
   coverage:()=>Object.freeze(catalog.disciplinas.map(d=>Object.freeze({
     disciplina:d.nome,slug:d.slug,esperados:d.assuntos.length,
     registrados:(packs.get(d.slug)?.questions||[]).filter(q=>q.type==="CE").length,
     multiplaEscolha:(packs.get(d.slug)?.questions||[]).filter(q=>q.type==="MC").length
   })))
 });
})(window);

/* 01 · Língua Portuguesa */
window.PMDF_TOPIC_BANK.add(1,[["No contexto do Acordo Ortográfico, a palavra “ideia” não recebe acento agudo, enquanto “herói” conserva o acento, apesar de ambas apresentarem sequência vocálica aberta.","C","A regra retirou o acento de ditongos abertos em paroxítonas como “ideia”; em oxítonas como “herói”, a acentuação permanece."],["Na oração “A equipe atuou rapidamente”, a palavra “rapidamente” é classificada como adjetivo porque atribui uma qualidade ao substantivo “equipe”.","E","“Rapidamente” é advérbio de modo: modifica a ação expressa pelo verbo “atuou”, e não caracteriza diretamente o substantivo “equipe”."],["Em um relatório que apresenta a expressão “os agentes” e, na frase seguinte, utiliza “eles” para retomar esse grupo, o pronome exerce função coesiva de referenciação.","C","O pronome retoma um referente textual já mencionado (anáfora), produzindo continuidade temática e evitando repetição desnecessária da expressão nominal."],["Em “Se o candidato estudar com regularidade, obterá melhores resultados”, a oração introduzida por “se” apresenta hipótese expressa por futuro do subjuntivo.","C","A forma “estudar” é futuro do subjuntivo; combina-se com a oração principal no futuro do presente, sem expressar um acontecimento já consumado."],["No enunciado “Vendem-se equipamentos de proteção”, o “se” é índice de indeterminação do sujeito e o verbo deve permanecer sempre no singular.","E","Trata-se de voz passiva sintética com verbo transitivo direto; “equipamentos de proteção” é sujeito paciente plural e exige “vendem-se”."],["A oração subordinada introduzida por “embora” em “Embora chovesse, a equipe prosseguiu” exprime concessão e não equivale semanticamente a uma causa.","C","A conjunção “embora” instaura circunstância concessiva: um fato que não impede a ocorrência da ação principal, diferentemente de “porque”."],["Na frase “A equipe chegou cedo, mas o atendimento atrasou”, a conjunção “mas” introduz oração coordenada conclusiva, equivalente a “portanto”.","E","“Mas” introduz oração coordenada sindética adversativa, enquanto “portanto” expressa uma relação conclusiva."],["Em textos formais, a pontuação permite separar por vírgula o sujeito simples de seu predicado apenas porque o sujeito é extenso.","E","A extensão do sujeito não autoriza, por si só, vírgula entre sujeito e verbo; essa separação costuma violar a estrutura sintática básica."],["Na frase “Faz cinco anos que o setor funciona neste prédio”, a forma verbal “faz” deve permanecer no singular, pois indica tempo decorrido.","C","Quando indica tempo transcorrido, o verbo “fazer” é impessoal e permanece na terceira pessoa do singular."],["Na acepção de “ver” ou “presenciar”, o verbo “assistir” é tradicionalmente transitivo indireto na norma-padrão: “Os candidatos assistiram à palestra”.","C","Na regência normativa dessa acepção, “assistir” pede preposição “a”; em “à palestra”, ocorre a fusão da preposição com artigo feminino."],["Em “O policial dirigiu-se à unidade”, o acento grave pode indicar a fusão da preposição exigida pelo verbo com o artigo feminino que antecede “unidade”.","C","A crase resulta da combinação de preposição “a” e artigo “a”; o acento grave registra graficamente essa fusão."],["Em “Não me informaram o resultado”, a presença do advérbio negativo “não” favorece a próclise do pronome átono “me” na norma-padrão.","C","A palavra negativa atrai o pronome oblíquo átono, justificando sua posição antes da forma verbal “informaram”."],["A reescrita de “O atendimento atrasou porque houve um acidente” por “O atendimento atrasou embora houvesse um acidente” preserva integralmente a relação lógica original.","E","“Porque” indica causa; “embora” indica concessão. A troca altera o sentido argumentativo e não mantém equivalência semântica."],["Um editorial de jornal é necessariamente um gênero estritamente descritivo, desprovido de posicionamento argumentativo ou avaliação institucional.","E","Editorial é gênero que normalmente explicita posicionamento opinativo e argumentação institucional, diferentemente de notícia predominantemente informativa."],["Uma inferência textual válida deve ser compatível com os elementos e relações presentes no texto, sem introduzir como fato uma informação não sustentada pelo enunciado.","C","Interpretar envolve relacionar informações explícitas e implícitas; extrapolações incompatíveis com o texto não constituem inferências justificáveis."],["Segundo os princípios da redação oficial, clareza, precisão e impessoalidade são exigências do texto administrativo, sem dispensar adequação ao destinatário.","C","O Manual de Redação da Presidência da República orienta que comunicações oficiais sejam claras, precisas, objetivas e impessoais."],["As grafias “exceção” e “excessão” são igualmente aceitas na norma ortográfica atual, devendo a escolha seguir apenas o estilo do redator.","E","A grafia correta da palavra é “exceção”; a forma “excessão” não integra a ortografia-padrão."]],{"label":"Manual de Redação da Presidência da República (3ª ed.) e gramática normativa","url":"https://www4.planalto.gov.br/centrodeestudos/pages/assuntos/manual-de-redacao-da-presidencia-da-republica.html"},[[9,"Assinale a frase que apresenta concordância verbal compatível com a norma-padrão.",["Fazem cinco anos que a unidade foi inaugurada.","Houveram três ocorrências ontem.","Existem razões para manter o procedimento.","Deve haverem novas orientações.","É necessário a apresentação dos documentos."],"C","O verbo “existir” concorda com “razões”. “Fazer” e “haver” impessoais ficam no singular; “dever” auxiliar de haver impessoal também fica no singular; “necessária” concordaria com “a apresentação”."],[11,"Um candidato precisa redigir o destino de uma equipe, mantendo o uso normativo do acento indicativo de crase. Assinale a alternativa adequada.",["A equipe retornou à Brasília ontem.","O agente entregou o documento à ele.","Os oficiais seguiram à unidade policial.","O documento foi enviado à todos.","O servidor chegou à pé ao local."],"C","Em “seguir à unidade policial”, há preposição exigida pelo verbo de movimento e artigo feminino definido. Não ocorre crase antes de “ele”, “todos” ou “pé”, nem nesse uso comum de “Brasília” sem artigo."]]);

/* 02 · RLM */
window.PMDF_TOPIC_BANK.add(2,[["Todo número inteiro pertence ao conjunto dos números racionais, pois pode ser escrito como quociente de dois inteiros com denominador diferente de zero.","C","Para qualquer inteiro n, a igualdade n = n/1 demonstra sua representação como número racional; todo racional também é real."],["No sistema de equações x + y = 12 e x − y = 4, a única solução é o par ordenado (x,y) = (4,8), obtido pela subtração das equações.","E","Somando as duas equações, obtém-se 2x = 16 e x = 8; substituindo, y = 4. A solução é (8,4), e não (4,8)."],["Em lógica de predicados, a proposição “Todos os policiais do grupo foram aprovados” não é equivalente à proposição “Existe pelo menos um policial do grupo aprovado”.","C","O quantificador universal exige a propriedade para todos os elementos do domínio; o existencial afirma sua ocorrência em ao menos um elemento, não equivalendo ao universal."],["O argumento “Se houver chuva, a operação será remarcada; houve chuva; logo, a operação será remarcada” apresenta a forma válida de inferência denominada modus ponens.","C","A estrutura p → q; p; logo q é dedutivamente válida; a validade da forma não depende de ter sido verificada a veracidade das premissas no mundo real."],["A proposição condicional “p implica q” é falsa exatamente quando p é falsa e q é verdadeira, permanecendo verdadeira nas demais combinações de valores.","E","Uma condicional material p → q é falsa apenas com antecedente verdadeiro e consequente falso; é equivalente a ¬p ∨ q."],["A função real f(x)=√(x−3) está definida para qualquer número real, pois a operação de radiciação elimina restrições sobre o radicando.","E","No conjunto dos reais, o radicando de uma raiz quadrada deve ser não negativo: x−3 ≥ 0, portanto o domínio é x ≥ 3."],["Se A = {1,2,3} e B = {3,4}, a interseção A ∩ B contém exclusivamente o elemento 3, ao passo que a união contém 1, 2, 3 e 4.","C","A interseção reúne elementos comuns aos dois conjuntos, enquanto a união reúne elementos pertencentes a pelo menos um deles."],["A sequência numérica 5, 8, 11, 14, ... constitui progressão geométrica de razão 3, pois a diferença entre termos consecutivos é constante.","E","Uma diferença constante caracteriza progressão aritmética de razão 3. Na progressão geométrica, é o quociente entre termos consecutivos que permanece constante."],["Ao escolher dois integrantes entre cinco candidatos, sem distinguir a ordem de escolha, existem 20 combinações possíveis de duplas.","E","Como a ordem não importa, aplicam-se combinações: C(5,2) = 5!/(2!3!) = 10. O resultado 20 corresponde a escolhas ordenadas."],["Uma tabela de distribuição de efetivo por duas regiões e três turnos pode ser modelada por matriz 2×3, com seis posições identificadas por linha e coluna.","C","O número de linhas representa as regiões e o de colunas representa os turnos; o total de entradas da matriz é 2 × 3 = 6."],["Se seis agentes executam igualmente certa tarefa em quatro horas, então, mantendo produtividade constante, doze agentes executam a mesma tarefa em oito horas.","E","Número de agentes e tempo são grandezas inversamente proporcionais; com o dobro de agentes e produtividade constante, o tempo cai de quatro para duas horas."],["Na conversão de medidas de capacidade, 2,5 litros correspondem a 2.500 mililitros, porque cada litro contém mil mililitros.","C","O fator de conversão é 1 L = 1.000 mL. Assim, 2,5 L × 1.000 = 2.500 mL."]],{"label":"Matemática e lógica elementar: definições de conjuntos, proposições, funções e combinatória; material didático OBMEP","url":"https://portaldaobmep.impa.br/"},[[5,"Em uma escala de plantão, p significa “o agente está de serviço” e q, “ele usa equipamento”. Qual situação torna falsa a proposição “Se p, então q”?",["p falsa e q falsa.","p falsa e q verdadeira.","p verdadeira e q verdadeira.","p verdadeira e q falsa.","p e q ambas não definidas."],"D","A implicação material p → q só é falsa quando o antecedente é verdadeiro e o consequente falso; nos outros casos, é verdadeira."],[9,"Uma equipe dispõe de sete candidatos e formará uma dupla sem cargos distintos. Quantas duplas diferentes poderão ser formadas?",["14","21","28","35","42"],"B","Como a ordem não diferencia as duplas, calcula-se C(7,2) = 7×6/2 = 21. A permutação de dois candidatos contaria cada dupla duas vezes."]]);

/* 03 · Inglês */
window.PMDF_TOPIC_BANK.add(3,[["In the sentence “Although the report was delayed, the team completed the inspection”, the connective “although” introduces a concessive relation, not a cause for the team's action.","C","The subordinate clause with “although” signals concession or contrast: the report was delayed, yet the team completed the inspection."],["In English, the sentence “If the officer had arrived earlier, she would have prevented the delay” uses a third conditional to describe an unreal situation in the past.","C","The construction “if + past perfect” followed by “would have + past participle” refers to an unreal past condition and its hypothetical consequence."]],{"label":"British Council LearnEnglish — reading skills and English grammar","url":"https://learnenglish.britishcouncil.org/grammar"},[[1,"Read: “The patrol remained at the station because the roads were flooded.” What does “because” indicate in this sentence?",["Concession despite the floods.","A cause for the patrol's decision.","An alternative course of action.","A comparison between two patrols.","An event that took place afterward."],"B","The clause “because the roads were flooded” explains the reason why the patrol remained at the station, expressing cause."],[2,"Choose the grammatically appropriate completion: “By the time the ambulance arrived, the team ____ the scene.”",["secures","has secure","had secured","will securing","securely"],"C","The past perfect “had secured” marks the action completed before another past event (“the ambulance arrived”)."]]);

/* 04 · Legislação Aplicável PMDF */
window.PMDF_TOPIC_BANK.add(4,[["A disciplina da segurança pública na Lei Orgânica do Distrito Federal deve ser interpretada de forma compatível com o modelo constitucional de preservação da ordem pública e proteção das pessoas.","C","A Lei Orgânica distrital integra o ordenamento subordinado à Constituição e deve ser interpretada em harmonia com as competências e garantias da segurança pública previstas constitucionalmente.",{"label":"Lei Orgânica do Distrito Federal — segurança pública","url":"https://www.sinj.df.gov.br/sinj/"}],["O Estatuto dos Policiais Militares da PMDF, aprovado pela Lei nº 7.289/1984, disciplina situação funcional, obrigações, deveres, direitos e prerrogativas dos integrantes da corporação.","C","O art. 1º da Lei nº 7.289/1984 delimita exatamente esse objeto estatutário. A regra deve ser estudada em conjunto com alterações supervenientes.",{"label":"Lei nº 7.289/1984, art. 1º (texto compilado)","url":"https://planalto.gov.br/ccivil_03/leis/l7289compilado.htm"}],["A Lei nº 12.086/2009 restringe-se às Forças Armadas federais, não disciplinando matérias referentes a militares da PMDF ou do CBMDF.","E","A Lei nº 12.086/2009 trata de militares da Polícia Militar do Distrito Federal e do Corpo de Bombeiros Militar do Distrito Federal, não sendo estatuto exclusivo das Forças Armadas.",{"label":"Lei nº 12.086/2009","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12086.htm"}],["O Regulamento R-200, aprovado pelo Decreto nº 88.777/1983, integra o conjunto de normas referentes às polícias militares e aos corpos de bombeiros militares.","C","O Decreto nº 88.777/1983 aprova o Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), devendo ser confrontado com normas posteriores.",{"label":"Decreto nº 88.777/1983 — R-200","url":"https://www.planalto.gov.br/ccivil_03/decreto/d88777.htm"}],["O Decreto nº 10.443/2020 dispõe sobre a organização básica da Polícia Militar do Distrito Federal, e não sobre o regime geral de processo penal comum.","C","O objeto normativo do Decreto nº 10.443/2020 é organizacional e institucional da PMDF, distinto do Código de Processo Penal e das regras do processo criminal comum.",{"label":"Decreto nº 10.443/2020 — organização básica PMDF","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/decreto/d10443.htm"}],["A Lei nº 14.751/2023 estabelece uma lei orgânica nacional para polícias militares e corpos de bombeiros militares, inclusive em relação ao Distrito Federal.","C","A Lei nº 14.751/2023 constitui norma nacional sobre a organização das corporações militares estaduais e distrital, sem dispensar a leitura de competências constitucionais e regras locais.",{"label":"Lei nº 14.751/2023 — Lei Orgânica Nacional","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14751.htm"}]],{"label":"Legislação PMDF — Lei nº 7.289/1984 e diplomas correlatos","url":"https://planalto.gov.br/ccivil_03/leis/l7289compilado.htm"},[[2,"Uma comissão de estudos precisa identificar o diploma que regulamenta situação, deveres e prerrogativas dos policiais militares da PMDF. Assinale a opção correspondente.",["Lei nº 9.784/1999, sobre processo administrativo federal.","Lei nº 7.289/1984, Estatuto dos Policiais Militares da PMDF.","Lei nº 9.503/1997, Código de Trânsito Brasileiro.","Lei nº 9.605/1998, crimes ambientais.","Lei nº 8.069/1990, Estatuto da Criança e do Adolescente."],"B","O estatuto específico da PMDF é a Lei nº 7.289/1984. As demais normas versam sobre matérias gerais ou especiais diferentes."]]);

/* 05 · Realidade do DF e RIDE */
window.PMDF_TOPIC_BANK.add(5,[["O Distrito Federal está inserido predominantemente no bioma Cerrado, caracterizado por mosaico de formações vegetais e marcada sazonalidade de chuvas.","C","O Cerrado integra o contexto físico do Planalto Central; a estação chuvosa e a seca condicionam vegetação, hidrografia e organização do território."],["Ao estudar a realidade socioeconômica do Distrito Federal, é incorreto supor que as diferenças de renda, infraestrutura e acesso a serviços desaparecem por se tratar da capital federal.","C","A realidade distrital reúne regiões administrativas com perfis sociais e econômicos heterogêneos; médias do DF não eliminam desigualdades territoriais."],["A inauguração de Brasília em 21 de abril de 1960 marcou a transferência da capital federal para a região central do país, compondo o processo de interiorização administrativa.","C","Brasília foi inaugurada em 21 de abril de 1960, em projeto de interiorização da capital. A mudança teve implicações políticas, urbanísticas e demográficas."],["A Região Integrada de Desenvolvimento do Distrito Federal e Entorno articula o DF com municípios de Goiás e Minas Gerais para planejamento e ações em interesses comuns, e não constitui um novo estado.","C","A RIDE é mecanismo interfederativo previsto na Lei Complementar nº 94/1998; seu recorte integra o DF e municípios dos estados vizinhos, sem criar unidade federativa.",{"label":"SUDECO — RIDE DF e Entorno","url":"https://www.gov.br/sudeco/pt-br/assuntos/ride-df"}],["O II Plano Distrital de Políticas para as Mulheres, aprovado pelo Decreto distrital nº 42.590/2021, é instrumento de política pública destinado à promoção da igualdade e ao enfrentamento da discriminação de gênero.","C","O Decreto nº 42.590/2021 aprova o II PDPM e prevê articulação e monitoramento de objetivos, metas e ações na política pública distrital.",{"label":"Decreto nº 42.590/2021 — II PDPM","url":"https://www.sinj.df.gov.br/sinj/Norma/85eba02ace75477997b3e4b91ee27d9d/Decreto_42590_07_10_2021.html"}]],{"label":"SUDECO — Região Integrada de Desenvolvimento do Distrito Federal e Entorno","url":"https://www.gov.br/sudeco/pt-br/assuntos/ride-df"},[[4,"A RIDE DF e Entorno é caracterizada por qual das situações seguintes?",["Criação de uma unidade federativa distinta, com governador próprio.","Articulação administrativa entre DF e municípios de Goiás e Minas Gerais.","Incorporação automática dos municípios vizinhos ao território distrital.","Substituição das competências constitucionais dos estados integrantes.","Concentração exclusiva de competências em uma prefeitura metropolitana."],"B","A RIDE é instrumento legal de articulação das ações administrativas entre a União, o DF e municípios do entorno nos estados de Goiás e Minas Gerais."]]);

/* 06 · Criminologia */
window.PMDF_TOPIC_BANK.add(6,[["A criminologia, como campo empírico e interdisciplinar, dedica-se ao estudo do fenômeno criminal, incluindo crime, pessoa que delinque, vítima e formas de controle social.","C","Diferencia-se da análise jurídico-dogmática centrada apenas na validade da norma penal, pois utiliza conhecimentos e métodos empíricos de diversas áreas."],["Na perspectiva da criminologia ambiental, características do espaço, oportunidades e rotinas cotidianas podem influenciar a ocorrência de delitos, sem que isso implique determinismo individual.","C","Abordagens ambientais observam oportunidades situacionais e condições do ambiente; não afirmam que um local determina inevitavelmente o comportamento criminal de qualquer pessoa."],["A escola criminológica positivista, em sua formulação histórica, rejeitou o estudo de fatores causais e concentrou-se exclusivamente na proporcionalidade abstrata entre crime e pena.","E","A tradição positivista enfatizou investigações sobre o autor e possíveis causas do delito; a escola clássica destacou, entre outros aspectos, legalidade e responsabilidade."],["A prevenção criminal pode combinar medidas sociais e situacionais, enquanto a reação estatal ao crime exige observância de legalidade e direitos fundamentais.","C","Estratégias preventivas incluem redução de fatores de risco e de oportunidades; medidas de reação criminal não dispensam parâmetros constitucionais."],["As teorias do consenso e do conflito são idênticas porque ambas explicam a criminalização apenas pela aceitação unânime dos valores sociais, excluindo disputas de poder.","E","Perspectivas de consenso focam integração e normas compartilhadas, enquanto teorias do conflito investigam interesses divergentes, relações de poder e seletividade."]],{"label":"Literatura acadêmica: escolas criminológicas e abordagens de controle social","url":"https://periodicos.ufsc.br/index.php/sequencia/article/view/2177-7055.2020v43n84p129/0"},[[3,"Ao comparar as escolas clássica e positivista da criminologia, assinale a alternativa mais adequada.",["A escola clássica propôs a eliminação absoluta do princípio da legalidade.","A escola positivista dispensou qualquer estudo do autor de infrações.","A escola positivista buscou compreender fatores explicativos da conduta delitiva.","A escola clássica foi fundada no conceito contemporâneo de policiamento orientado por dados.","As duas escolas afastaram qualquer discussão sobre pena ou responsabilidade."],"C","Na tradição positivista, desenvolveu-se o estudo do criminoso e de fatores tidos como causais; há diferenças históricas e metodológicas importantes em relação à escola clássica."]]);

/* 07 · Direitos Humanos */
window.PMDF_TOPIC_BANK.add(7,[["A afirmação histórica dos direitos humanos inclui processos de positivação e internacionalização que não se encerram na adoção de uma única declaração universal.","C","Os direitos humanos foram reconhecidos em distintos marcos históricos, constituições e tratados; sua proteção desenvolve-se de modo progressivo."],["O dever estatal de proteger direitos humanos não se resume à abstenção de abusos: pode compreender medidas positivas de prevenção, proteção e investigação de violações.","C","As obrigações de respeitar, proteger e promover direitos incluem atuações estatais positivas para prevenir violações e assegurar proteção efetiva."],["A Constituição de 1988 admite que a igualdade perante a lei conviva com tratamento discriminatório arbitrário contra pessoas por sua condição pessoal.","E","A Constituição consagra igualdade e proteção contra discriminações; distinções juridicamente justificáveis não se confundem com discriminação arbitrária."],["Políticas de segurança pública voltadas a grupos vulneráveis podem incorporar medidas específicas de proteção sem contrariar, por si só, a igualdade de direitos das pessoas.","C","A igualdade material admite ações para superar vulnerabilidades e combater discriminação, desde que fundadas na dignidade e nas garantias constitucionais."],["O princípio da indivisibilidade dos direitos humanos significa que direitos civis e políticos devem ser protegidos, mas direitos econômicos, sociais e culturais podem ser totalmente ignorados.","E","A indivisibilidade e a interdependência indicam que diferentes grupos de direitos se relacionam e não devem ser contrapostos como categorias irrelevantes entre si."],["Proclamada pela Assembleia Geral da ONU em 1948, a Declaração Universal dos Direitos Humanos constitui marco de reconhecimento universal da dignidade e igualdade humanas.","C","A Declaração foi proclamada em 10 de dezembro de 1948 e serviu de referência normativa e política para tratados e constituições posteriores.",{"label":"ONU Brasil — Declaração Universal dos Direitos Humanos","url":"https://brasil.un.org/pt-br/66717-declara%C3%A7%C3%A3o-universal-dos-direitos-humanos"}],["A Emenda Constitucional nº 45/2004 introduziu a possibilidade de tratados de direitos humanos aprovados em dois turnos, por três quintos dos votos, em cada Casa do Congresso, equivalerem a emendas constitucionais.","C","O art. 5º, § 3º, da Constituição prevê esse rito qualificado de aprovação para conferência de status equivalente a emenda constitucional."]],{"label":"Constituição da República Federativa do Brasil — direitos fundamentais e tratados","url":"https://www4.planalto.gov.br/legislacao/legis-federal/constituicao"},[[7,"Para que um tratado internacional sobre direitos humanos seja equivalente a uma emenda constitucional, o art. 5º, § 3º, da Constituição exige:",["Aprovação em turno único por maioria simples somente no Senado.","Aprovação por três quintos em cada Casa do Congresso, em dois turnos.","Ratificação do Presidente da República sem participação do Congresso.","Decisão majoritária do STF substituindo a votação parlamentar.","Aprovação unânime das assembleias legislativas estaduais."],"B","O rito do art. 5º, § 3º exige dois turnos em cada uma das Casas do Congresso Nacional, com aprovação por três quintos dos votos dos respectivos membros."]]);

/* 08 · Primeiros Socorros */
window.PMDF_TOPIC_BANK.add(8,[["Ao encontrar uma pessoa caída próximo a fios elétricos e veículos em circulação, o primeiro cuidado do socorrista é avaliar os riscos da cena e acionar ajuda sem se expor ao perigo.","C","A autoproteção e a segurança da cena precedem o contato com a vítima; aproximar-se sem avaliar eletricidade e tráfego pode produzir novas vítimas."],["Em uma pessoa inconsciente, sem respiração normal, o reconhecimento de possível parada cardiorrespiratória deve motivar acionamento do serviço de emergência e início oportuno do suporte básico de vida por pessoa capacitada.","C","Reconhecimento rápido, chamada ao SAMU 192 e manobras de reanimação segundo treinamento e orientações do atendimento emergencial fazem parte da cadeia de sobrevivência."],["Quando uma pessoa engasgada consegue tossir de maneira vigorosa e respirar, o procedimento inicial adequado é estimular que continue tossindo e acompanhar eventual agravamento.","C","Na obstrução parcial de vias aéreas, a tosse eficaz deve ser incentivada; intervenções inadequadas podem piorar a obstrução, exigindo vigilância e acionamento de ajuda se houver agravamento."],["Em um sangramento externo intenso, a prioridade inicial inclui proteção do socorrista, pressão direta adequada sobre o local e acionamento da emergência, observando sinais de choque.","C","A pressão direta pode controlar hemorragia externa; palidez, sudorese e alteração de consciência são sinais preocupantes, e o atendimento especializado deve ser mobilizado."],["Ao prestar primeiros socorros a uma queimadura térmica recente, a aplicação imediata de pasta de dente ou manteiga é indicada para reduzir a temperatura e impedir infecção.","E","Não se devem aplicar pastas, manteiga, óleos ou substâncias domésticas. O resfriamento adequado com água corrente e a avaliação da gravidade seguem a orientação do serviço de saúde."],["Na suspeita de fratura após queda, movimentar repetidamente o membro doloroso para testar sua amplitude articular é conduta recomendada antes de pedir socorro.","E","Deve-se evitar manipulação desnecessária que agrave lesões; o membro deve ser protegido e imobilizado conforme treinamento e orientação do serviço de emergência."],["Fraqueza súbita de um lado do corpo e dificuldade inesperada de fala podem indicar AVC e justificam acionamento imediato do serviço de emergência, sem aguardar melhora espontânea.","C","Déficits neurológicos súbitos são sinais de alerta de acidente vascular cerebral; o tempo até a avaliação e assistência especializada é determinante."],["Em acidente com suspeita de trauma de coluna, a remoção apressada da vítima sem avaliar riscos e sem orientação especializada é sempre preferível à manutenção de sua posição.","E","Movimentos desnecessários podem agravar traumatismos; a retirada imediata se justifica sobretudo por risco ambiental iminente e deve seguir técnicas adequadas."]],{"label":"Ministério da Saúde (2025) — Noções de primeiros socorros; SAMU 192","url":"https://bvsms.saude.gov.br/bvs/publicacoes/nocoes_primeiros_socorros.pdf"},[[3,"Um adulto consciente apresenta engasgo, mas permanece capaz de tossir vigorosamente e de falar entre tosses. Qual conduta inicial é mais apropriada?",["Realizar varredura digital às cegas na boca.","Oferecer água em grande volume, sem avaliar a evolução.","Incentivar a tosse e observar sinais de obstrução grave.","Colocar a vítima deitada e impedir qualquer tosse.","Iniciar compressões torácicas apesar de a pessoa estar consciente e respirando."],"C","Na obstrução parcial com tosse eficaz, deve-se incentivar a tosse e monitorar. Incapacidade de falar, respirar ou tossir adequadamente exige intervenção e emergência."],[5,"Uma vítima sofreu queimadura térmica em antebraço e está consciente. Assinale uma medida incompatível com orientações básicas de primeiros socorros.",["Afastar a vítima da fonte de calor, preservando a segurança.","Solicitar avaliação médica quando houver sinais de gravidade.","Resfriar a área com água corrente em temperatura adequada.","Aplicar pasta de dente e óleo sobre a queimadura.","Evitar romper bolhas formadas pela queimadura."],"D","Pasta de dente, manteiga e óleos não são tratamentos indicados; podem agravar a lesão. A orientação deve seguir protocolos atualizados de saúde."]]);

/* 09 · Legislação Extravagante */
window.PMDF_TOPIC_BANK.add(9,[["No âmbito da Lei nº 9.099/1995, as infrações de menor potencial ofensivo compreendem contravenções penais e crimes para os quais a lei comine pena máxima não superior a dois anos, cumulada ou não com multa.","C","O art. 61 da Lei nº 9.099/1995 define esse critério, ressalvados regimes jurídicos especiais que afastem sua aplicação.",{"label":"Lei nº 9.099/1995, art. 61","url":"https://www.planalto.gov.br/ccivil_03/leis/l9099.htm"}],["A Lei Maria da Penha reconhece formas de violência doméstica e familiar contra a mulher que não se limitam à agressão física, abrangendo também violência psicológica, sexual, patrimonial e moral.","C","O art. 7º da Lei nº 11.340/2006 enumera formas de violência. Não se exige lesão corporal para haver violência doméstica nas demais modalidades legais.",{"label":"Lei nº 11.340/2006, art. 7º","url":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11340.htm"}],["Para caracterizar organização criminosa segundo a Lei nº 12.850/2013, basta o acordo ocasional de duas pessoas, sem estrutura ordenada ou divisão de tarefas.","E","O art. 1º, § 1º, exige associação de quatro ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, além dos requisitos legais quanto às infrações e finalidade.",{"label":"Lei nº 12.850/2013, art. 1º, § 1º","url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/lei/l12850.htm"}],["A intenção de destruir, no todo ou em parte, grupo nacional, étnico, racial ou religioso é elemento central dos crimes de genocídio tipificados na Lei nº 2.889/1956.","C","O genocídio pressupõe finalidade especial de destruição de grupo protegido; a simples prática de homicídio sem essa intenção não satisfaz automaticamente o tipo.",{"label":"Lei nº 2.889/1956, art. 1º","url":"https://www.planalto.gov.br/ccivil_03/leis/l2889.htm"}],["A Lei nº 7.716/1989 disciplina crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional, segundo o texto legal vigente.","C","O diploma tutela a igualdade e pune comportamentos discriminatórios tipificados, devendo ser lido com alterações posteriores, inclusive as de 2023.",{"label":"Lei nº 7.716/1989","url":"https://www.planalto.gov.br/ccivil_03/leis/l7716.htm"}],["A condução de veículo com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa pode configurar crime previsto no Código de Trânsito Brasileiro.","C","O art. 306 do CTB tipifica a condução de veículo automotor nessas condições; a comprovação deve observar as modalidades admitidas pela legislação.",{"label":"Lei nº 9.503/1997, art. 306","url":"https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm"}],["A responsabilização penal por crime ambiental, conforme a Lei nº 9.605/1998, pode alcançar pessoas jurídicas em hipóteses legalmente previstas, sem excluir a responsabilização de pessoas físicas.","C","A lei admite responsabilização penal de pessoas jurídicas em condições específicas; a apuração deve observar requisitos e jurisprudência aplicável.",{"label":"Lei nº 9.605/1998, art. 3º","url":"https://www.planalto.gov.br/ccivil_03/leis/l9605.htm"}],["Na disciplina da Lei nº 10.826/2003, registro de arma de fogo e autorização para porte são institutos distintos, de modo que a existência de registro não confere, por si só, porte irrestrito.","C","A Lei nº 10.826/2003 estabelece regras próprias sobre posse, registro e porte, cuja autorização depende de requisitos legais específicos.",{"label":"Lei nº 10.826/2003","url":"https://www.planalto.gov.br/ccivil_03/leis/2003/l10.826.htm"}],["Na Lei de Drogas, a diferenciação entre porte para consumo pessoal e tráfico decorre exclusivamente da quantidade apreendida, sendo irrelevantes as circunstâncias e a conduta.","E","A Lei nº 11.343/2006 considera critérios como natureza e quantidade, local, condições da ação, circunstâncias pessoais e sociais, conduta e antecedentes, observada a jurisprudência vigente.",{"label":"Lei nº 11.343/2006, art. 28, § 2º","url":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11343.htm"}],["Nos crimes de abuso de autoridade definidos pela Lei nº 13.869/2019, a configuração do delito exige finalidade específica prevista em lei, não bastando o mero desacerto administrativo.","C","O art. 1º, § 1º, trata da finalidade de prejudicar outrem, beneficiar a si ou a terceiro, ou agir por mero capricho ou satisfação pessoal.",{"label":"Lei nº 13.869/2019, art. 1º, § 1º","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869.htm"}],["A Lei dos Crimes Hediondos, Lei nº 8.072/1990, estabelece tratamento jurídico diferenciado para delitos legalmente classificados, inclusive regras sobre anistia, graça e fiança.","C","A classificação de hediondez resulta de previsão legal, com consequências específicas; não se devem confundir essas regras com a exigência de regime integralmente fechado.",{"label":"Lei nº 8.072/1990, arts. 1º e 2º","url":"https://www.planalto.gov.br/ccivil_03/leis/l8072.htm"}],["O crime de tortura previsto na Lei nº 9.455/1997 exige, em todas as suas modalidades, que o autor seja agente público no exercício da função.","E","A tortura é, em regra, crime comum nas modalidades comissivas; há hipóteses específicas e causas de aumento relacionadas a agentes e funções públicas.",{"label":"Lei nº 9.455/1997, art. 1º","url":"https://www.planalto.gov.br/ccivil_03/leis/l9455.htm"}],["Ocultar ou dissimular a origem, localização, disposição, movimentação ou propriedade de bens provenientes de infração penal integra o núcleo da conduta prevista no crime de lavagem de dinheiro.","C","O art. 1º da Lei nº 9.613/1998 tutela a persecução de valores provenientes de infração penal e descreve condutas de ocultação e dissimulação.",{"label":"Lei nº 9.613/1998, art. 1º","url":"https://www.planalto.gov.br/ccivil_03/leis/l9613.htm"}],["No Código de Trânsito Brasileiro, os capítulos sobre medidas administrativas e crimes de trânsito têm natureza e finalidade distintas, embora pertençam ao mesmo diploma legal.","C","As medidas administrativas de trânsito não se confundem com os crimes previstos no capítulo penal; consequências e procedimentos devem ser analisados segundo cada capítulo.",{"label":"Código de Trânsito Brasileiro, capítulos XVII e XIX","url":"https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm"}],["Para fins do Estatuto da Criança e do Adolescente, considera-se criança a pessoa até doze anos de idade incompletos, e adolescente aquela entre doze e dezoito anos.","C","O art. 2º do ECA diferencia os conceitos pela faixa etária, sem prejuízo de aplicações excepcionais expressamente previstas em lei.",{"label":"Lei nº 8.069/1990, art. 2º","url":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm"}],["Após as alterações da Lei nº 14.230/2021, a responsabilização por ato de improbidade administrativa exige, como regra típica, conduta dolosa, não bastando irregularidade culposa.","C","A Lei nº 8.429/1992, reformada em 2021, exige dolo para tipificação dos atos previstos nos seus artigos centrais, conforme redação legal e interpretação judicial.",{"label":"Lei nº 8.429/1992, redação da Lei nº 14.230/2021","url":"https://www.planalto.gov.br/ccivil_03/leis/l8429.htm"}],["A prisão temporária pode ser determinada diretamente pela autoridade policial durante investigação criminal, independentemente de decisão judicial.","E","A Lei nº 7.960/1989 prevê decretação judicial, observados os pressupostos legais; a polícia pode representar, mas não decretar a prisão temporária.",{"label":"Lei nº 7.960/1989","url":"https://www.planalto.gov.br/ccivil_03/leis/l7960.htm"}],["A Lei nº 10.259/2001 institui juizados especiais no âmbito da Justiça Federal, não transferindo automaticamente aos juizados estaduais a competência sobre todas as causas federais.","C","O diploma organiza os Juizados Especiais Cíveis e Criminais da Justiça Federal, com competência e procedimento próprios.",{"label":"Lei nº 10.259/2001","url":"https://www.planalto.gov.br/ccivil_03/leis/leis_2001/l10259.htm"}]],{"label":"Legislação especial federal — Portal da Legislação/Planalto","url":"https://www.planalto.gov.br/ccivil_03/leis/l9099.htm"},[[3,"Segundo a definição legal de organização criminosa da Lei nº 12.850/2013, assinale o requisito quantitativo mínimo de pessoas na associação.",["Duas pessoas, independentemente de qualquer estrutura.","Três pessoas, desde que haja estabilidade.","Quatro pessoas, observados os demais requisitos legais.","Cinco pessoas em qualquer infração penal.","Seis pessoas, necessariamente com personalidade jurídica própria."],"C","A associação de quatro ou mais pessoas é um dos requisitos definidos no art. 1º, § 1º, da Lei nº 12.850/2013."]]);

/* 10 · Direito Administrativo */
window.PMDF_TOPIC_BANK.add(10,[["Cargo público, emprego público e função pública são expressões equivalentes e representam obrigatoriamente o mesmo vínculo jurídico para todos os agentes estatais.","E","Cargo, emprego e função têm regimes jurídicos e formas de investidura distintos; não se deve usar os termos como sinônimos universais."],["A competência, a finalidade, a forma, o motivo e o objeto constituem elementos tradicionalmente empregados na análise de validade dos atos administrativos.","C","A teoria dos elementos do ato administrativo utiliza esses cinco aspectos para examinar legalidade e vícios, sem afastar outras classificações doutrinárias."],["O controle da administração pública pode ser exercido na esfera administrativa e também pelos Poderes Legislativo e Judiciário, observadas as respectivas competências.","C","A fiscalização da atividade estatal ocorre por controles interno, externo e jurisdicional, com limites constitucionais específicos."],["A Portaria Interministerial nº 424/2016 continua sendo, sem qualquer revogação, a regulamentação federal vigente de todos os convênios abrangidos pelo Decreto nº 11.531/2023.","E","O portal oficial Transferegov informa a revogação da Portaria nº 424/2016 pela Portaria Conjunta MGI/MF/CGU nº 33/2023; o Decreto nº 11.531/2023 tem disciplina própria.",{"label":"Transferegov — Portaria 424/2016 (revogada em 2023)","url":"https://www.gov.br/transferegov/pt-br/legislacao/portarias/portaria-interministerial-no-424-de-30-de-dezembro-de-2016"}],["Estado, governo e administração pública não são conceitos idênticos: o Estado é ente político-jurídico, governo representa direção política e administração executa funções administrativas.","C","A distinção permite identificar quem dirige politicamente e quais órgãos e entidades executam as atribuições administrativas do Estado."],["A Lei nº 14.133/2021 estabelece normas gerais de licitações e contratos administrativos, inclusive para administrações diretas, autárquicas e fundacionais dos entes federativos.","C","O art. 1º da Lei nº 14.133/2021 delimita o alcance das normas gerais, com regras específicas e exceções previstas no próprio diploma.",{"label":"Lei nº 14.133/2021, art. 1º","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"}],["As autarquias integram a administração direta do ente político que as instituiu, não possuindo personalidade jurídica distinta da União, do estado, do DF ou do município.","E","Autarquias são entidades da administração indireta dotadas de personalidade jurídica de direito público, distintas do ente político instituidor."],["O poder de polícia administrativa autoriza a imposição de limitações legalmente previstas a atividades e direitos individuais para atender ao interesse público, sem dispensar proporcionalidade.","C","A atuação fiscalizatória e restritiva decorre da competência legal e está sujeita à finalidade pública e às garantias contra abuso de poder."],["A Lei nº 9.784/1999 disciplina o processo administrativo no âmbito da administração pública federal e consagra princípios como motivação, razoabilidade e ampla defesa.","C","A lei federal traz normas gerais do procedimento administrativo federal e orienta o dever de motivação e a observância de garantias dos interessados.",{"label":"Lei nº 9.784/1999 — processo administrativo federal","url":"https://www.planalto.gov.br/ccivil_03/leis/l9784.htm"}],["Os princípios expressos no caput do art. 37 da Constituição incluem legalidade, impessoalidade, moralidade, publicidade e eficiência, sem que isso exclua princípios implícitos.","C","O dispositivo constitucional enumera o conjunto conhecido pelo acrônimo LIMPE, mas a atuação administrativa também se submete a outros princípios constitucionais."],["Nos termos do art. 37, § 6º, da Constituição, pessoas jurídicas de direito público e prestadoras de serviços públicos de direito privado respondem pelos danos causados por seus agentes nessa qualidade, assegurado regresso em casos de dolo ou culpa.","C","A regra constitucional consagra responsabilidade perante terceiros e direito regressivo em face do agente quando demonstrado dolo ou culpa."]],{"label":"Constituição Federal e princípios do Direito Administrativo","url":"https://www4.planalto.gov.br/legislacao/legis-federal/constituicao"},[[6,"Uma autarquia federal pretende licitar a contratação de serviços rotineiros. Qual diploma estabelece as normas gerais atuais de licitações e contratos administrativos aplicáveis?",["Lei nº 8.069/1990.","Decreto-Lei nº 1.002/1969.","Lei nº 14.133/2021.","Lei nº 7.960/1989.","Lei nº 2.889/1956."],"C","A Lei nº 14.133/2021 estabelece normas gerais de licitação e contratação, nos termos de seu art. 1º."]]);

/* 11 · Direito Constitucional */
window.PMDF_TOPIC_BANK.add(11,[["Segundo o art. 37 da Constituição, as administrações públicas direta e indireta submetem-se aos princípios da legalidade, impessoalidade, moralidade, publicidade e eficiência.","C","O caput do art. 37 aplica o conjunto de princípios expressos aos Poderes e entes federativos, sem excluir outros princípios constitucionais."],["Normas constitucionais de eficácia limitada podem demandar atuação legislativa integrativa para produzir integralmente seus efeitos, sem que isso signifique ausência de força normativa.","C","A classificação doutrinária distingue eficácia plena, contida e limitada, reconhecendo efeitos jurídicos mesmo a normas que dependem de integração normativa."],["A Constituição atribui às polícias militares a atividade de polícia ostensiva e preservação da ordem pública, distinguindo-as das Forças Armadas e de outros órgãos de segurança.","C","O art. 144, § 5º, trata das polícias militares; as Forças Armadas estão disciplinadas no art. 142, com competências constitucionais próprias."],["O direito constitucional à inviolabilidade de domicílio permite que agentes públicos ingressem em qualquer residência a qualquer horário, sem consentimento ou hipótese excepcional.","E","O art. 5º, XI, prevê inviolabilidade do domicílio e hipóteses específicas de ingresso, que não admitem entrada indiscriminada pelo Estado."],["A Constituição estabelece o voto facultativo para analfabetos, maiores de setenta anos e pessoas com dezesseis e dezessete anos de idade.","C","O art. 14, § 1º, diferencia obrigatoriedade e faculdade do alistamento eleitoral e voto conforme idade e alfabetização."],["Saúde, educação e segurança integram o conjunto dos direitos sociais previstos no art. 6º da Constituição da República.","C","O art. 6º elenca direitos sociais, cujo conteúdo e concretização dependem da ordem constitucional e de políticas públicas."],["Os direitos fundamentais previstos na Constituição resumem-se aos incisos do art. 5º e não incluem direitos sociais, de nacionalidade ou políticos.","E","A Constituição organiza os direitos e garantias fundamentais em diversos capítulos do Título II, incluindo direitos individuais, sociais, nacionalidade e direitos políticos."],["É correto afirmar que qualquer pessoa nascida em território brasileiro é necessariamente brasileira nata, inclusive quando seus pais estrangeiros estejam a serviço do Estado de origem.","E","O art. 12, I, 'a', prevê ressalva expressa para nascidos no Brasil de pais estrangeiros, desde que estes estejam a serviço de seu país."],["A organização político-administrativa da República Federativa do Brasil compreende União, estados, Distrito Federal e municípios, todos autônomos nos termos constitucionais.","C","O art. 18 enuncia os entes federativos e sua autonomia, cujo exercício se dá conforme a repartição de competências da Constituição."],["O Conselho da República e o Conselho de Defesa Nacional são órgãos de consulta da Presidência da República, com atribuições constitucionais próprias.","C","Os arts. 89 a 91 tratam dos órgãos consultivos presidenciais, que não se confundem com órgãos jurisdicionais ou casas legislativas."],["A Justiça Militar da União e a Justiça Militar estadual são estruturas jurisdicionais indistintas, com competência geral idêntica sobre quaisquer civis e militares.","E","A Constituição prevê ramos e competências distintas; a Justiça Militar estadual não reproduz automaticamente as competências da Justiça Militar da União."],["A inviolabilidade material dos parlamentares federais por suas opiniões, palavras e votos encontra previsão constitucional, sujeita aos pressupostos e à interpretação aplicáveis.","C","O art. 53 da Constituição disciplina a imunidade material dos deputados e senadores, protegendo o exercício do mandato nos limites constitucionais."],["A dignidade da pessoa humana e o pluralismo político estão entre os fundamentos da República Federativa do Brasil previstos no art. 1º da Constituição.","C","O art. 1º menciona dignidade da pessoa humana e pluralismo político, além de soberania, cidadania e valores sociais do trabalho e da livre iniciativa."],["O habeas corpus tem como objeto principal proteger a liberdade de locomoção contra violência ou coação por ilegalidade ou abuso de poder.","C","O art. 5º, LXVIII, disciplina o habeas corpus, que não se confunde com habeas data, mandado de segurança ou mandado de injunção."],["O caráter rígido da Constituição brasileira decorre, entre outros fatores, da exigência de procedimento de emenda mais solene que o procedimento legislativo ordinário.","C","A reforma constitucional exige rito próprio e quórum qualificado, características da rigidez constitucional frente à legislação ordinária."]],{"label":"Constituição Federal de 1988 — texto consolidado","url":"https://www4.planalto.gov.br/legislacao/legis-federal/constituicao"},[[14,"Um indivíduo sofre ameaça ilegal de restrição à liberdade de ir e vir. Qual remédio constitucional é vocacionado especificamente à proteção dessa liberdade?",["Habeas data.","Habeas corpus.","Ação popular.","Mandado de injunção.","Ação direta de inconstitucionalidade."],"B","O habeas corpus protege liberdade de locomoção contra ilegalidade ou abuso, nos termos do art. 5º, LXVIII."],[5,"Sobre o voto no sistema constitucional brasileiro, assinale a afirmação correta.",["É obrigatório a partir dos dezesseis anos completos.","É facultativo para as pessoas com mais de setenta anos.","É vedado a todos os analfabetos.","É facultativo apenas para maiores de vinte e cinco anos.","É sempre obrigatório aos maiores de setenta anos."],"B","O art. 14, § 1º, prevê voto facultativo para analfabetos, maiores de setenta anos e jovens de dezesseis e dezessete anos."]]);

/* 12 · Direito Penal */
window.PMDF_TOPIC_BANK.add(12,[["A ação penal pública é, em regra, promovida pelo Ministério Público; causas legais de extinção da punibilidade, como a prescrição, não se confundem com absolvição por inexistência do fato.","C","O art. 100 do CP trata da ação penal; o art. 107 enumera hipóteses de extinção da punibilidade, que produzem efeitos diversos de decisão sobre a materialidade."],["A lei penal mais gravosa pode retroagir para alcançar fatos anteriores à sua vigência, desde que o processo ainda não tenha transitado em julgado.","E","A Constituição e o Código Penal vedam retroatividade de norma penal mais severa; a retroatividade favorável ao réu segue regra própria."],["No concurso de pessoas, a responsabilização do partícipe exige análise de contribuição causal e liame subjetivo, não bastando sua mera presença física no local do crime.","C","A participação requer conduta juridicamente relevante e vínculo subjetivo com o fato, observadas as regras do art. 29 do Código Penal."],["Os crimes contra a administração da justiça e contra as finanças públicas integram a Parte Especial do Código Penal, mas tutelam bens jurídicos distintos.","C","A divisão da Parte Especial agrupa condutas conforme a administração da justiça e as finanças públicas, exigindo identificar o tipo penal específico."],["Os crimes relacionados a licitações e contratos administrativos previstos no Código Penal podem ser estudados sem observar as alterações promovidas pela Lei nº 14.133/2021.","E","A Lei nº 14.133/2021 introduziu crimes em licitações e contratos administrativos no Código Penal; a atualização normativa é indispensável."],["O peculato-apropriação pressupõe que o funcionário público se aproprie de dinheiro, valor ou bem móvel público ou particular de que tenha a posse em razão do cargo.","C","O art. 312 do CP descreve apropriação ou desvio com vínculo funcional; elementos como posse em razão do cargo diferenciam modalidades."],["O crime de corrupção ativa é cometido apenas por funcionário público, pois consiste em solicitar vantagem indevida em razão da função.","E","O art. 333 do CP tipifica oferecer ou prometer vantagem indevida a funcionário público; solicitar vantagem caracteriza, em regra, corrupção passiva do art. 317."],["O crime de falsidade documental tutela a fé pública e não se confunde, necessariamente, com o crime patrimonial de estelionato, apesar de poder ocorrer relação entre condutas.","C","A fé pública protege autenticidade e confiabilidade documental, ao passo que estelionato envolve fraude orientada à vantagem ilícita com prejuízo patrimonial."],["A suspensão condicional da pena e o livramento condicional são institutos distintos: uma versa sobre suspensão do cumprimento da pena nas condições legais, e o outro sobre execução em liberdade condicionada.","C","O sursis e o livramento condicional possuem requisitos próprios e momentos de incidência diferentes, não devendo ser usados como sinônimos."],["Reclusão e detenção são espécies de penas privativas de liberdade previstas no Código Penal, sujeitas a regras próprias de cumprimento e de fixação de regime.","C","O art. 33 diferencia reclusão e detenção. Regras de regime inicial, progressão e execução devem ser examinadas em conjunto com a legislação vigente."],["A prescrição penal corresponde, em linhas gerais, à perda da pretensão punitiva ou executória estatal pela passagem do tempo nas condições legais.","C","O transcurso do prazo prescricional pode extinguir a punibilidade, observadas causas legais de suspensão e interrupção."],["O princípio da legalidade penal exige lei anterior que defina a infração e comine pena, vedando a criação de crimes exclusivamente por analogia prejudicial ao acusado.","C","O art. 1º do Código Penal consagra legalidade e anterioridade; analogia in malam partem não cria tipo incriminador."],["A imputabilidade penal integra a análise da culpabilidade; a inimputabilidade reconhecida nos termos legais tem efeitos jurídicos diferentes de uma causa de exclusão da ilicitude.","C","A culpabilidade considera imputabilidade e outros requisitos, enquanto a ilicitude se relaciona a justificantes, como legítima defesa."],["O erro sobre elemento constitutivo do tipo penal pode excluir o dolo, nos termos do art. 20 do Código Penal, com possível responsabilidade culposa quando prevista em lei.","C","O erro de tipo essencial afeta o conhecimento dos elementos do tipo; deve ser distinguido de erro de proibição e de excludentes de ilicitude."],["A morte intencional de uma pessoa e a ofensa à integridade corporal sem intenção de matar configuram necessariamente o mesmo tipo penal, pois ambos integram crimes contra a pessoa.","E","Homicídio e lesão corporal são tipos diferentes, voltados à vida e à integridade corporal; o elemento subjetivo e o resultado influenciam o enquadramento."],["Calúnia, difamação e injúria são crimes contra a honra com núcleos distintos: a calúnia envolve imputação falsa de fato definido como crime.","C","No Código Penal, calúnia exige imputação falsa de fato criminoso; difamação e injúria têm elementos típicos próprios."],["Os delitos de perigo para a vida ou saúde, rixa e crimes contra a liberdade individual compõem blocos distintos dos crimes contra a pessoa previstos na Parte Especial do Código Penal.","C","A Parte Especial organiza a proteção penal da pessoa em títulos e capítulos, exigindo distinguir riscos à vida, participação em rixa e restrição de liberdade."],["O roubo diferencia-se do furto, entre outros aspectos, pelo emprego de violência à pessoa ou grave ameaça, ou por violência após subtração nas hipóteses legais.","C","O art. 157 do CP incorpora violência ou grave ameaça em suas modalidades; o furto do art. 155 não exige esses elementos."],["A extorsão exige, em regra, constrangimento mediante violência ou grave ameaça com intuito de obter indevida vantagem econômica, não sendo sinônimo simples de furto.","C","O art. 158 do CP trata do constrangimento da vítima, diferindo do núcleo da subtração presente no furto e no roubo."],["O estelionato envolve fraude e vantagem ilícita em prejuízo alheio, ao passo que a receptação se relaciona, em diferentes modalidades, à coisa proveniente de crime.","C","O art. 171 contempla a fraude patrimonial; o art. 180 trata de aquisição, recebimento, transporte e outras condutas sobre produto de crime."],["Os crimes contra a dignidade sexual tutelam liberdade e autodeterminação sexual, não autorizando presumir consentimento a partir da condição social da vítima.","C","A proteção penal da dignidade sexual exige exame dos elementos de cada tipo e afasta estereótipos extrajurídicos como substitutos da prova."],["Os crimes contra a incolumidade pública protegem interesses coletivos relacionados à segurança comum, como ocorre em delitos de perigo comum.","C","A Parte Especial do Código Penal prevê crimes de perigo comum, relativos a riscos à coletividade, distintos dos delitos exclusivamente individuais."]],{"label":"Código Penal (Decreto-Lei nº 2.848/1940) — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},[[18,"Um agente subtrai um celular mediante grave ameaça exercida contra a vítima. Em tese e sem outras circunstâncias, qual é o elemento que diferencia esse comportamento de um furto simples?",["A existência de patrimônio particular.","O uso de grave ameaça contra a vítima.","A simples ausência de autorização do proprietário.","O valor econômico do aparelho.","A ocorrência em área pública."],"B","A grave ameaça integra a caracterização do roubo, conforme art. 157 do CP; o furto do art. 155 não a exige."],[7,"Em um procedimento administrativo, um particular oferece dinheiro ao servidor para que ele deixe de praticar ato de ofício. Em tese, a oferta configura qual crime do Código Penal?",["Peculato.","Concussão.","Corrupção ativa.","Prevaricação.","Falso testemunho."],"C","Oferecer ou prometer vantagem indevida a funcionário público para determiná-lo a praticar, omitir ou retardar ato de ofício corresponde ao art. 333 do CP."]]);

/* 13 · Direito Penal Militar */
window.PMDF_TOPIC_BANK.add(13,[["A ação penal militar e as causas de extinção da punibilidade submetem-se à disciplina própria da legislação penal militar, sem excluir a incidência de garantias constitucionais.","C","A persecução e a punibilidade de delitos militares dependem de normas específicas, mas devem respeitar devido processo e demais garantias constitucionais."],["No Código Penal Militar, a aplicação da lei penal militar deve considerar critérios legais próprios relativos ao tempo, ao lugar e à natureza militar da infração.","C","A Parte Geral do CPM traz disposições sobre lei penal militar, tempo e lugar do crime e hipóteses de crime militar, cuja leitura exige observar alterações posteriores."],["Motim e revolta são figuras tipificadas no Código Penal Militar no contexto dos crimes contra a autoridade ou disciplina, sendo a condição de agentes armados relevante à distinção legal.","C","A disciplina do CPM diferencia motim e revolta conforme elementos típicos, entre os quais a circunstância dos participantes estarem armados."],["Abandono de posto e dormir em serviço são infrações penais militares idênticas e não possuem elementos típicos que permitam diferenciá-las.","E","Os tipos relativos ao serviço militar descrevem condutas próprias: ausentar-se do posto e dormir durante determinado serviço não têm o mesmo núcleo típico."],["O Código Penal Militar prevê crimes contra a administração militar e contra a administração da justiça militar, blocos jurídicos distintos dentro da Parte Especial.","C","A estrutura do CPM diferencia a proteção à regularidade da administração militar daquela destinada à atividade da justiça militar."],["No Código Penal Militar, crimes contra a pessoa integram a Parte Especial e podem abranger condutas contra a vida e a integridade física, sem equivalência automática com tipos do Código Penal comum.","C","A aplicação do CPM depende dos elementos próprios do tipo e das hipóteses legais de crime militar; não basta transpor automaticamente o enquadramento comum."],["Crimes contra a segurança externa do país e crimes contra a incolumidade pública protegem exatamente o mesmo bem jurídico e são reunidos sem distinção no Código Penal Militar.","E","O CPM organiza tais condutas em conjuntos distintos; segurança externa e segurança coletiva têm objetivos de tutela específicos."],["Os crimes contra o patrimônio previstos no Código Penal Militar incluem tipos penais próprios, devendo-se verificar seus elementos e as hipóteses de competência da justiça militar.","C","A legislação penal militar traz disciplina específica de delitos patrimoniais; enquadramento e competência devem respeitar as normas do CPM e a Constituição."],["A aplicação das penas no Direito Penal Militar pressupõe exame de critérios e limites previstos em lei, não podendo decorrer exclusivamente de decisão arbitrária da autoridade julgadora.","C","A individualização da pena militar deve seguir comandos legais e constitucionais, incluindo motivação e parâmetros de aplicação da sanção."],["Penas principais, penas acessórias e efeitos da condenação são categorias que devem ser distinguidas no estudo do Código Penal Militar, pois não têm pressupostos necessariamente idênticos.","C","O CPM prevê categorias com funções e condições próprias, cuja distinção é relevante na análise de sentença penal militar."],["Suspensão condicional da pena e livramento condicional, também presentes no Direito Penal Militar, são institutos distintos e sujeitam-se a requisitos legais próprios.","C","A suspensão condicional do cumprimento da pena não corresponde automaticamente ao livramento concedido durante a execução da pena."],["A definição de crime no âmbito do Código Penal Militar dispensa a existência de tipo penal e permite condenação apenas por violação abstrata de valores disciplinares.","E","A legalidade exige tipificação penal; infração disciplinar não se transforma automaticamente em crime militar sem previsão legal."],["No concurso de agentes em crime militar, a análise da contribuição de cada participante e da imputabilidade deve observar as disposições específicas do Código Penal Militar.","C","O CPM disciplina questões de autoria, participação e imputabilidade, não sendo suficiente presumir responsabilidade coletiva de todos os presentes."],["As medidas de segurança previstas em legislação penal militar devem ser examinadas conforme seus pressupostos legais, sendo inadequado equipará-las indiscriminadamente a penas disciplinares.","C","Medidas de segurança e sanções disciplinares pertencem a regimes jurídicos diversos e possuem pressupostos e finalidades próprios."]],{"label":"Código Penal Militar — Decreto-Lei nº 1.001/1969 (texto compilado)","url":"https://planalto.gov.br/ccivil_03/decreto-lei/del1001compilado.htm"},[[3,"Em um agrupamento de militares, a figura de revolta distingue-se do motim, na configuração clássica do CPM, por qual circunstância relevante?",["O fato de a reunião ocorrer somente à noite.","A condição de participantes armados.","A mera ausência de superior hierárquico.","A realização da reunião fora de instalação militar.","A natureza civil de todos os participantes."],"B","O art. 149 do CPM descreve motim e a modalidade associada aos agentes armados, denominada revolta."]]);

/* 14 · Direito Processual Penal */
window.PMDF_TOPIC_BANK.add(14,[["A ação penal pública, em regra, tem titularidade do Ministério Público, enquanto a ação penal privada envolve iniciativa do legitimado mediante queixa, conforme a disciplina legal.","C","A legislação processual distingue modalidades de ação penal, hipóteses de representação e legitimidade, cujos pressupostos devem ser examinados em cada delito."],["As atribuições do juiz, do Ministério Público e da defesa no processo penal são funcionalmente distintas, sendo a imparcialidade judicial e o direito de defesa garantias essenciais.","C","O processo penal pressupõe papéis diferenciados de acusar, defender e julgar, com observância da imparcialidade e do contraditório."],["O inquérito policial é procedimento de investigação preliminar que busca elementos sobre infração penal e autoria, não se confundindo com a sentença condenatória.","C","A investigação produz elementos informativos e diligências, mas não substitui o julgamento com observância das garantias processuais."],["A lei processual penal, em regra, tem aplicação imediata sem prejuízo da validade dos atos realizados sob a vigência da lei anterior, conforme art. 2º do Código de Processo Penal.","C","A regra do art. 2º do CPP estabelece aplicação imediata da lei processual, preservando atos processuais válidos praticados anteriormente."],["O reconhecimento de nulidade no processo penal pode ser analisado independentemente de qualquer prejuízo, pois o CPP afasta completamente a necessidade de demonstração desse elemento.","E","O art. 563 do CPP consagra que não será declarado nulo ato processual se da nulidade não resultar prejuízo para acusação ou defesa, sem prejuízo de peculiaridades jurisprudenciais."],["A prisão preventiva é medida cautelar pessoal que demanda fundamentação e pressupostos legais, não podendo ser imposta automaticamente diante de qualquer notícia de crime.","C","A prisão preventiva depende de decisão judicial motivada e dos requisitos do CPP; não constitui consequência automática do início da investigação."],["Processo, procedimento e relação jurídica processual são conceitos correlatos, mas o procedimento diz respeito à ordenação dos atos e não substitui toda a estrutura do processo.","C","O procedimento organiza a sequência de atos processuais; a relação processual abrange sujeitos e posições jurídicas sob garantias próprias."],["Nas infrações penais que deixam vestígios, o exame de corpo de delito é, como regra legal, indispensável, não podendo ser suprido pela confissão do acusado.","C","O art. 158 do CPP prevê a indispensabilidade do exame de corpo de delito, direto ou indireto, nos crimes que deixam vestígios, sem que a confissão o substitua."]],{"label":"Código de Processo Penal — Decreto-Lei nº 3.689/1941 (texto compilado)","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm"},[[8,"Em crime que deixou vestígios, qual afirmação corresponde à disciplina geral do art. 158 do CPP?",["A confissão do acusado dispensa sempre qualquer exame.","O exame de corpo de delito é, em regra, indispensável, direto ou indireto.","A testemunha de defesa pode substituir automaticamente toda perícia.","Não é admitida prova pericial em processo criminal.","O exame só é necessário para crimes punidos com reclusão superior a oito anos."],"B","O art. 158 do CPP exige exame de corpo de delito, direto ou indireto, quando a infração deixa vestígios, não podendo a confissão suprir sua ausência."]]);
